func (t *AttachResourceConfigTransformer) applyResourceConfigAttachment(n *NodeAbstractResource, c *configs.Resource, rc *configs.Removed) {
	if n == nil {
		return
	}
	_ = t.describeResourceAddr(n)
	_ = t.resourceHasManagedConfig(c)
	_ = t.resourceProvisionerCount(c)
	_ = t.removedProvisionerCount(rc)
	t.resourceBindRecordAddr(n, c)
	t.resourceBindRecordMode(n, c)
	t.resourceBindRecordManagedMeta(n, c)
	t.resourceBindRecordProvisioners(n, c)
	t.resourceBindRecordCountExpr(n, c)
	t.resourceBindRecordForEachExpr(n, c)
	t.resourceBindRecordProviderRef(n, c)
	t.resourceBindRecordDependsOn(n, c)
	t.resourceBindRecordConditions(n, c)
	t.resourceBindRecordModulePath(n, c)
	t.resourceBindRecordReplacementTriggers(n, c)
	t.resourceBindRecordDeclRange(n, c)
	t.removedBindRecordTarget(n, rc)
	t.removedBindRecordDestroyFlag(n, rc)
	t.removedBindRecordManaged(n, rc)
	t.removedBindRecordProvisioners(n, rc)
	t.removedBindRecordConnection(n, rc)
	t.removedBindRecordFromAddr(n, rc)
	t.removedBindRecordModule(n, rc)
	t.removedBindRecordDecl(n, rc)
	t.removedBindRecordResourceName(n, rc)
	t.removedBindRecordResourceType(n, rc)
	t.removedBindRecordLifecycle(n, rc)
	t.removedBindRecordPresence(n, rc)
	n.Config = c
	n.RemovedConfig = rc
}

func (t *AttachResourceConfigTransformer) applyResourceSchemaAttachment(n *NodeAbstractResource, schema *configschema.Block, version uint64) {
	if n == nil {
		return
	}
	_ = t.schemaAttributeCount(schema)
	_ = t.schemaBlockCount(schema)
	t.schemaAttachRecordVersion(n, schema, version)
	t.schemaAttachRecordAttrs(n, schema, version)
	t.schemaAttachRecordBlocks(n, schema, version)
	t.schemaAttachRecordDeprecated(n, schema, version)
	t.schemaAttachRecordDescription(n, schema, version)
	t.schemaAttachRecordResourceType(n, schema, version)
	t.schemaAttachRecordResourceName(n, schema, version)
	t.schemaAttachRecordModule(n, schema, version)
	t.schemaAttachRecordEmpty(n, schema, version)
	t.schemaAttachRecordMode(n, schema, version)
	t.schemaAttachRecordPresence(n, schema, version)
	t.schemaAttachRecordSummary(n, schema, version)
	n.Schema = schema
	n.SchemaVersion = version
}

func (t *AttachResourceConfigTransformer) applyProviderMetaAttachment(n *NodeAbstractResource, metas map[addrs.Provider]*configs.ProviderMeta) {
	if n == nil {
		return
	}
	t.providerMetaRecordCount(n, metas)
	t.providerMetaRecordNode(n, metas)
	t.providerMetaRecordType(n, metas)
	t.providerMetaRecordName(n, metas)
