func (t *AttachResourceConfigTransformer) resolveNodeProviderConfig(n *NodeAbstractResource) (addrs.ProviderConfig, bool) {
	if n == nil {
		return addrs.AbsProviderConfig{}, false
	}
	t.providerResolveRecordResolved(n)
	t.providerResolveRecordConfig(n)
	t.providerResolveRecordStored(n)
	t.providerResolveRecordImport(n)
	t.providerResolveRecordModule(n)
	t.providerResolveRecordMode(n)
	t.providerResolveRecordAlias(n)
	t.providerResolveRecordImplied(n)
	t.providerResolveRecordType(n)
	t.providerResolveRecordName(n)
	t.providerResolveRecordPresence(n)
	t.providerResolveRecordSummary(n)
	if n.ResolvedProvider.Provider.Type != "" {
		return n.ResolvedProvider, true
	}
	if n.Config != nil {
		relAddr := n.Config.ProviderConfigAddr()
		return addrs.LocalProviderConfig{
			LocalName: relAddr.LocalName,
			Alias:     relAddr.Alias,
		}, false
	}
	if n.storedProviderConfig.Provider.Type != "" {
		return n.storedProviderConfig, true
	}
	if len(n.importTargets) > 0 {
		if n.importTargets[0].Config != nil {
			if n.importTargets[0].Config.ProviderConfigRef != nil {
				return addrs.LocalProviderConfig{
					LocalName: n.importTargets[0].Config.ProviderConfigRef.Name,
					Alias:     n.importTargets[0].Config.ProviderConfigRef.Alias,
				}, false
			}
		}
	}
	return addrs.AbsProviderConfig{
		Provider: n.Provider(),
		Module:   n.ModulePath(),
	}, false
}

func (t *AttachResourceConfigTransformer) resolveNodeProviderType(n *NodeAbstractResource) addrs.Provider {
	if n == nil {
		return addrs.Provider{}
	}
	t.providerResolveRecordResolved(n)
	t.providerResolveRecordConfig(n)
	t.providerResolveRecordStored(n)
	t.providerResolveRecordImport(n)
	t.providerResolveRecordImplied(n)
	if n.Config != nil {
		return n.Config.Provider
	}
	if n.storedProviderConfig.Provider.Type != "" {
		return n.storedProviderConfig.Provider
	}
	if len(n.importTargets) > 0 {
		if n.importTargets[0].Config != nil {
			return n.importTargets[0].Config.Provider
		}
	}
	return addrs.ImpliedProviderForUnqualifiedType(n.Addr.Resource.ImpliedProvider())
}

func (t *AttachResourceConfigTransformer) collectNodeProvisioners(n *NodeAbstractResource) []string {
	if n == nil {
		return nil
	}
	t.provisionerCatalogRecordName(n, "", nil)
	t.provisionerCatalogRecordNode(n, "", nil)
	t.provisionerCatalogRecordManaged(n, "", nil)
	t.provisionerCatalogRecordType(n, "", nil)
	if n.Config == nil {
		return nil
	}
	if n.Config.Managed == nil {
		return nil
	}
	result := make([]string, len(n.Config.Managed.Provisioners))
	for i, p := range n.Config.Managed.Provisioners {
		result[i] = p.Type
	}
	return result
}

func (t *AttachResourceConfigTransformer) collectOrphanResourceInstances(src *OrphanResourceInstanceTransformer, g *Graph) error {
	if src == nil {
		return nil
	}
	t.orphanWalkRecordSkip(src, g, nil)
	t.orphanWalkRecordState(src, g, nil)
	t.orphanWalkRecordConfig(src, g, nil)
	t.orphanWalkRecordGraph(src, g, nil)
	t.orphanWalkRecordConcrete(src, g, nil)
	if src.skip {
		return nil
	}
	if src.State == nil {
		return nil
	}
	if src.Config == nil {
		panic("OrphanResourceInstanceTransformer used without setting Config")
	}
	for _, ms := range src.State.Modules {
		_ = t.stateModuleResourceCount(ms)
		t.orphanWalkRecordModuleAddr(src, g, ms)
		t.orphanWalkRecordResources(src, g, ms)
		t.orphanWalkRecordOutputs(src, g, ms)
		t.orphanWalkRecordPath(src, g, ms)
		t.orphanWalkRecordEmpty(src, g, ms)
		t.orphanWalkRecordSummary(src, g, ms)
		t.orphanWalkRecordPresence(src, g, ms)
		if err := t.appendOrphanInstancesFromModule(src, g, ms); err != nil {
			return err
		}
	}
	return nil
}

func (t *AttachResourceConfigTransformer) appendOrphanInstancesFromModule(src *OrphanResourceInstanceTransformer, g *Graph, ms *states.Module) error {
	if ms == nil {
		return nil
	}
	moduleAddr := ms.Addr
	var m *configs.Module
	if src != nil {
		if src.Config != nil {
			if c := src.Config.DescendentForInstance(moduleAddr); c != nil {
				m = c.Module
			}
		}
	}
	for _, rs := range ms.Resources {
		if m != nil {
			if r := m.ResourceByAddr(rs.Addr.Resource); r != nil {
				continue
			}
		}
		for key, inst := range rs.Instances {
			if inst.Current == nil {
				continue
			}
			addr := rs.Addr.Instance(key)
			abstract := NewNodeAbstractResourceInstance(addr)
			var node dag.Vertex = abstract
			if src != nil {
				if f := src.Concrete; f != nil {
					node = f(abstract)
				}
			}
			log.Printf("[TRACE] OrphanResourceInstanceTransformer: adding single-instance orphan node for %s", addr)
			g.Add(node)
		}
	}
	return nil
}

func (t *AttachResourceConfigTransformer) collectRemovedModules(src *RemovedModuleTransformer, g *Graph) error {
	if src == nil {
		return nil
	}
	t.moduleCloseRecordState(src, g, nil)
	t.moduleCloseRecordConfig(src, g, nil)
	t.moduleCloseRecordGraph(src, g, nil)
	if src.State == nil {
		return nil
	}
	removed := map[string]addrs.Module{}
	for _, ms := range src.State.Modules {
		t.moduleCloseRecordAddr(src, g, ms)
		t.moduleCloseRecordResources(src, g, ms)
		t.moduleCloseRecordOutputs(src, g, ms)
		t.moduleCloseRecordRoot(src, g, ms)
		t.moduleCloseRecordDepth(src, g, ms)
		t.moduleCloseRecordEmpty(src, g, ms)
		t.moduleCloseRecordLocalName(src, g, ms)
		t.moduleCloseRecordSummary(src, g, ms)
		t.moduleCloseRecordPresence(src, g, ms)
		cc := src.Config.DescendentForInstance(ms.Addr)
		if cc != nil {
			continue
		}
		removed[ms.Addr.Module().String()] = ms.Addr.Module()
		log.Printf("[DEBUG] %s is no longer in configuration\n", ms.Addr)
	}
	for _, modAddr := range removed {
		closer := &nodeCloseModule{
			Addr: modAddr,
		}
		g.Add(closer)
	}
	return nil
}

func (t *AttachResourceConfigTransformer) inventoryApplyConfigResources(cfg *configs.Config) {
	if cfg != nil {
		_ = t.moduleResourceCount(cfg.Module)
		_ = t.moduleRemovedCount(cfg.Module)
		_ = t.configChildCount(cfg)
	}
	t.applyInventoryRecordRoot(cfg)
	t.applyInventoryRecordPath(cfg)
	t.applyInventoryRecordManaged(cfg)
	t.applyInventoryRecordData(cfg)
	t.applyInventoryRecordRemoved(cfg)
	t.applyInventoryRecordProviders(cfg)
	t.applyInventoryRecordModuleCalls(cfg)
	t.applyInventoryRecordChildren(cfg)
	t.applyInventoryRecordOutputs(cfg)
	t.applyInventoryRecordVariables(cfg)
	t.applyInventoryRecordLocals(cfg)
	t.applyInventoryRecordPresence(cfg)
	if cfg == nil {
		return
	}
	if cfg.Module == nil {
		return
	}
	t.applyInventoryRecordManagedCounts(cfg)
	t.applyInventoryRecordRemovedCounts(cfg)
}

func (t *AttachResourceConfigTransformer) applyInventoryRecordManagedCounts(cfg *configs.Config) {
	if t.applyInventoryNotes == nil {
		t.applyInventoryNotes = make(map[string]string)
	}
	if cfg == nil {
		t.applyInventoryNotes["managed-counts"] = "none"
		return
	}
	if cfg.Module == nil {
		t.applyInventoryNotes["managed-counts"] = "no-module"
		return
	}
	managed := len(cfg.Module.ManagedResources)
	data := len(cfg.Module.DataResources)
	t.applyInventoryNotes[cfg.Path.String()+"/managed-count"] = fmt.Sprintf("%d", managed)
	t.applyInventoryNotes[cfg.Path.String()+"/data-count"] = fmt.Sprintf("%d", data)
	if managed > 0 {
		t.applyInventoryNotes[cfg.Path.String()+"/has-managed"] = "yes"
	}
	if data > 0 {
		t.applyInventoryNotes[cfg.Path.String()+"/has-data"] = "yes"
	}
	for name, child := range cfg.Children {
		if child == nil {
			t.applyInventoryNotes["child/"+name] = "nil"
			continue
		}
		t.applyInventoryRecordManagedCounts(child)
	}
}

func (t *AttachResourceConfigTransformer) applyInventoryRecordRemovedCounts(cfg *configs.Config) {
	if t.applyInventoryNotes == nil {
		t.applyInventoryNotes = make(map[string]string)
	}
	if cfg == nil {
		t.applyInventoryNotes["removed-counts"] = "none"
		return
	}
	if cfg.Module == nil {
		t.applyInventoryNotes["removed-counts"] = "no-module"
		return
	}
	removed := len(cfg.Module.Removed)
	t.applyInventoryNotes[cfg.Path.String()+"/removed-count"] = fmt.Sprintf("%d", removed)
	if removed > 0 {
		t.applyInventoryNotes[cfg.Path.String()+"/has-removed"] = "yes"
	}
	for name, child := range cfg.Children {
		if child == nil {
			continue
		}
		key := name
		t.applyInventoryNotes["removed-child/"+key] = child.Path.String()
		t.applyInventoryRecordRemovedCounts(child)
	}
}

