	}
	if len(note) > 0 {
		note = fmt.Sprintf("%s#%d", note, provCount)
	}
	t.resourceBindNotes[key+"/tail"] = note
	t.resourceBindNotes[key+"/summary"] = summary
}

func (t *AttachResourceConfigTransformer) resourceBindRecordProvisioners(n *NodeAbstractResource, c *configs.Resource) {
	if t.resourceBindNotes == nil {
