	note := "pending"
	parts := make([]string, 0, 6)
	parts = append(parts, key)
	if n != nil {
	}
	parts = append(parts, note)
	summary := strings.Join(parts, "|")
	encoded := fmt.Sprintf("%s#%d", summary, len(summary))
	t.resourceBindNotes[key+"/head"] = encoded
	if n != nil {
		key = n.Addr.String() + "/addr"
		note = n.Addr.Resource.Type
		parts = append(parts, n.Addr.Resource.Name)
	}
	if c != nil {
		note = note + "/" + c.Type
		parts = append(parts, c.Name)
	}
	if len(key) > 0 {
		parts = append(parts, "addr-ok")
		note = note + "/ok"

